#include "SchemaPolicy.h"
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#define NODES 4096
#define MAX_BYTES 65536
/* A bounded AST of the one already-owned schema snapshot; no engine objects. */
typedef struct {unsigned char kind;unsigned first,next,count,start,end,str,units;bool control;} Node;
typedef struct {const unsigned char*b;size_t n,p;Node nodes[NODES];unsigned used;char strings[MAX_BYTES+1];unsigned chars;} Parser;
static void ws(Parser*p){while(p->p<p->n&&(p->b[p->p]==' '||p->b[p->p]=='\n'||p->b[p->p]=='\r'||p->b[p->p]=='\t'))p->p++;}
static int hex(unsigned char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static bool u4(Parser*p,uint32_t*out){if(p->n-p->p<4)return false;uint32_t v=0;for(unsigned i=0;i<4;i++){int h=hex(p->b[p->p++]);if(h<0)return false;v=(v<<4)|(unsigned)h;}*out=v;return true;}
static bool emit(Parser*p,uint32_t cp){unsigned char b[4];unsigned n=0;if(cp<0x80)b[n++]=cp;else if(cp<0x800){b[n++]=0xc0|(cp>>6);b[n++]=0x80|(cp&63);}else if(cp<0x10000){b[n++]=0xe0|(cp>>12);b[n++]=0x80|((cp>>6)&63);b[n++]=0x80|(cp&63);}else{b[n++]=0xf0|(cp>>18);b[n++]=0x80|((cp>>12)&63);b[n++]=0x80|((cp>>6)&63);b[n++]=0x80|(cp&63);}if(p->chars+n>=MAX_BYTES)return false;memcpy(p->strings+p->chars,b,n);p->chars+=n;return true;}
static bool string(Parser*p,Node*t){if(p->b[p->p++]!='"')return false;t->str=p->chars;while(p->p<p->n){uint32_t cp=p->b[p->p++];if(cp=='"'){if(p->chars>=MAX_BYTES)return false;p->strings[p->chars++]=0;return true;}if(cp<0x20)return false;if(cp=='\\'){if(p->p>=p->n)return false;unsigned char c=p->b[p->p++];if(c=='u'){if(!u4(p,&cp))return false;if(cp>=0xd800&&cp<=0xdbff){uint32_t low;if(p->n-p->p<6||p->b[p->p++]!='\\'||p->b[p->p++]!='u'||!u4(p,&low)||low<0xdc00||low>0xdfff)return false;cp=0x10000+((cp-0xd800)<<10)+(low-0xdc00);}else if(cp>=0xdc00&&cp<=0xdfff)return false;}else if(c=='"'||c=='\\'||c=='/')cp=c;else if(c=='b')cp=8;else if(c=='f')cp=12;else if(c=='n')cp=10;else if(c=='r')cp=13;else if(c=='t')cp=9;else return false;}else if(cp>=0x80){unsigned extra;uint32_t min;if(cp>=0xc2&&cp<=0xdf){extra=1;min=0x80;cp&=31;}else if(cp>=0xe0&&cp<=0xef){extra=2;min=0x800;cp&=15;}else if(cp>=0xf0&&cp<=0xf4){extra=3;min=0x10000;cp&=7;}else return false;for(unsigned i=0;i<extra;i++){if(p->p>=p->n||(p->b[p->p]&0xc0)!=0x80)return false;cp=(cp<<6)|(p->b[p->p++]&63);}if(cp<min||cp>0x10ffff||(cp>=0xd800&&cp<=0xdfff))return false;}if(cp<0x20)return false;t->units+=cp>0xffff?2:1;t->control|=cp<0x20;if(!emit(p,cp))return false;}return false;}
static unsigned value(Parser*p,unsigned depth){ws(p);if(depth>8||p->p>=p->n||p->used+1>=NODES)return 0;unsigned id=++p->used;Node*t=&p->nodes[id];t->start=(unsigned)p->p;unsigned char c=p->b[p->p];if(c=='"'){t->kind='s';if(!string(p,t))return 0;}else if(c=='['||c=='{'){t->kind=c;p->p++;ws(p);unsigned prev=0;if(p->p<p->n&&p->b[p->p]==(c=='['?']':'}'))p->p++;else for(;;){unsigned child=value(p,depth+1);if(!child)return 0;if(t->kind=='{'&&p->nodes[child].kind!='s')return 0;if(prev)p->nodes[prev].next=child;else t->first=child;prev=child;t->count++;if(t->kind=='{'){for(unsigned k=t->first;k&&k!=child;){if(!strcmp(p->strings+p->nodes[k].str,p->strings+p->nodes[child].str))return 0;unsigned val=p->nodes[k].next;k=val?p->nodes[val].next:0;}ws(p);if(p->p>=p->n||p->b[p->p++]!=':')return 0;unsigned v=value(p,depth+1);if(!v)return 0;p->nodes[prev].next=v;prev=v;t->count++;}ws(p);if(p->p>=p->n)return 0;c=p->b[p->p++];if(c==(t->kind=='['?']':'}'))break;if(c!=',')return 0;}}else if(c=='t'||c=='f'||c=='n'){const char*lit=c=='t'?"true":c=='f'?"false":"null";size_t n=strlen(lit);if(p->n-p->p<n||memcmp(p->b+p->p,lit,n))return 0;t->kind=c;p->p+=n;}else{t->kind='d';if(c=='-')p->p++;if(p->p>=p->n||!isdigit(p->b[p->p]))return 0;if(p->b[p->p]=='0')p->p++;else while(p->p<p->n&&isdigit(p->b[p->p]))p->p++;if(p->p<p->n&&(p->b[p->p]=='.'||p->b[p->p]=='e'||p->b[p->p]=='E'))return 0;}t->end=(unsigned)p->p;return id;}
static unsigned get(Parser*p,unsigned obj,const char*key){if(!obj||p->nodes[obj].kind!='{')return 0;for(unsigned k=p->nodes[obj].first;k;){unsigned v=p->nodes[k].next;if(!strcmp(p->strings+p->nodes[k].str,key))return v;k=v?p->nodes[v].next:0;}return 0;}
static bool keys(Parser*p,unsigned obj,const char*const*allowed){if(!obj||p->nodes[obj].kind!='{')return false;for(unsigned k=p->nodes[obj].first;k;){const char*s=p->strings+p->nodes[k].str;bool ok=false;for(unsigned i=0;allowed[i];i++)if(!strcmp(s,allowed[i]))ok=true;if(!ok)return false;unsigned v=p->nodes[k].next;k=v?p->nodes[v].next:0;}return true;}
static bool name(Parser*p,unsigned n,bool optional){if(!n||p->nodes[n].kind=='n')return optional;Node*t=&p->nodes[n];const char*s=p->strings+t->str;return t->kind=='s'&&t->units&&t->units<=256&&!t->control&&s[0]!='_'&&strncmp(s,"sqlite_",7);}
static bool equal(Parser*p,unsigned a,unsigned b){if(!a||p->nodes[a].kind=='n')return !b||p->nodes[b].kind=='n';return b&&p->nodes[b].kind=='s'&&!strcmp(p->strings+p->nodes[a].str,p->strings+p->nodes[b].str);}
static bool boolean(Parser*p,unsigned n,bool optional){return (!n&&optional)||(n&&(p->nodes[n].kind=='t'||p->nodes[n].kind=='f'));}
static bool validate(Parser*p,unsigned root){if(!root||p->nodes[root].kind!='['||p->nodes[root].count>64)return false;const char*const ck[]={"name","idName","embedded","properties","indexes","version",NULL};const char*const pk[]={"name","type","target",NULL};const char*const ik[]={"name","properties","unique","hash",NULL};const char*types[]={"Bool","Byte","Int","Float","Long","Double","DateTime","String","Object","Json","BoolList","ByteList","IntList","FloatList","LongList","DoubleList","DateTimeList","StringList","ObjectList"};unsigned totalp=0,totali=0;for(unsigned c=p->nodes[root].first;c;c=p->nodes[c].next){if(!keys(p,c,ck)||!name(p,get(p,c,"name"),false)||!name(p,get(p,c,"idName"),true)||!boolean(p,get(p,c,"embedded"),true))return false;for(unsigned q=p->nodes[root].first;q!=c;q=p->nodes[q].next)if(equal(p,get(p,q,"name"),get(p,c,"name")))return false;unsigned version=get(p,c,"version");if(version){Node*t=&p->nodes[version];if(t->kind!='d'||t->end-t->start>3||p->b[t->start]=='-')return false;unsigned n=0;for(unsigned j=t->start;j<t->end;j++)n=n*10+p->b[j]-'0';if(n>255)return false;}unsigned props=get(p,c,"properties"),idx=get(p,c,"indexes");if(!props||p->nodes[props].kind!='['||p->nodes[props].count>256||(idx&&(p->nodes[idx].kind!='['||p->nodes[idx].count>128)))return false;totalp+=p->nodes[props].count;totali+=idx?p->nodes[idx].count:0;if(totalp>1024||totali>512)return false;if(get(p,c,"embedded")&&p->nodes[get(p,c,"embedded")].kind=='t'&&idx&&p->nodes[idx].count)return false;
for(unsigned pr=p->nodes[props].first;pr;pr=p->nodes[pr].next){if(!keys(p,pr,pk)||!name(p,get(p,pr,"name"),true)||!name(p,get(p,pr,"target"),true))return false;unsigned ty=get(p,pr,"type");if(!ty||p->nodes[ty].kind!='s')return false;const char*type=p->strings+p->nodes[ty].str;bool known=false;for(unsigned i=0;i<19;i++)if(!strcmp(type,types[i]))known=true;if(!known)return false;for(unsigned q=p->nodes[props].first;q!=pr;q=p->nodes[q].next)if(equal(p,get(p,q,"name"),get(p,pr,"name")))return false;unsigned target=get(p,pr,"target");bool object=!strcmp(type,"Object")||!strcmp(type,"ObjectList");if(object){bool found=false;for(unsigned q=p->nodes[root].first;q;q=p->nodes[q].next)if(equal(p,get(p,q,"name"),target)&&get(p,q,"embedded")&&p->nodes[get(p,q,"embedded")].kind=='t')found=true;if(!found)return false;}else if(target&&p->nodes[target].kind!='n')return false;}
for(unsigned ix=idx?p->nodes[idx].first:0;ix;ix=p->nodes[ix].next){if(!keys(p,ix,ik)||!name(p,get(p,ix,"name"),false)||!boolean(p,get(p,ix,"unique"),false)||!boolean(p,get(p,ix,"hash"),false))return false;for(unsigned q=p->nodes[idx].first;q!=ix;q=p->nodes[q].next)if(equal(p,get(p,q,"name"),get(p,ix,"name")))return false;unsigned list=get(p,ix,"properties");if(!list||p->nodes[list].kind!='['||!p->nodes[list].count||p->nodes[list].count>256)return false;for(unsigned n=p->nodes[list].first;n;n=p->nodes[n].next){if(!name(p,n,false))return false;unsigned found=0;for(unsigned pr=p->nodes[props].first;pr;pr=p->nodes[pr].next)if(equal(p,get(p,pr,"name"),n))found=pr;if(!found)return false;const char*type=p->strings+p->nodes[get(p,found,"type")].str;size_t len=strlen(type);if(!strcmp(type,"Float")||!strcmp(type,"Double")||!strcmp(type,"Object")||!strcmp(type,"Json")||(len>=4&&!strcmp(type+len-4,"List")))return false;if(!strcmp(type,"String")&&p->nodes[get(p,ix,"hash")].kind!='t'&&p->nodes[n].next)return false;}}
}return true;}
bool TIOCaptureValidateSchema(const unsigned char*b,size_t n){if(!b||!n||n>65536)return false;Parser*p=calloc(1,sizeof(*p));if(!p)return false;p->b=b;p->n=n;unsigned root=value(p,1);ws(p);bool ok=root&&p->p==n&&validate(p,root);memset(p,0,sizeof(*p));free(p);return ok;}
typedef struct{unsigned char*b;size_t n;} Output;
static bool out(Output*o,const void*b,size_t n){if(n>65536-o->n)return false;memcpy(o->b+o->n,b,n);o->n+=n;return true;}
static bool quoted(Output*o,const char*s){if(!out(o,"\"",1))return false;for(const unsigned char*p=(const void*)s;*p;p++){if((*p=='"'||*p=='\\')&&!out(o,"\\",1))return false;if(!out(o,p,1))return false;}return out(o,"\"",1);}
static bool canonical(Parser*p,unsigned id,Output*o){Node*t=&p->nodes[id];if(t->kind=='s')return quoted(o,p->strings+t->str);if(t->kind=='n')return out(o,"null",4);if(t->kind=='t')return out(o,"true",4);if(t->kind=='f')return out(o,"false",5);if(t->kind=='d')return out(o,p->b+t->start,t->end-t->start);if(t->kind=='['){if(!out(o,"[",1))return false;bool first=true;for(unsigned c=t->first;c;c=p->nodes[c].next){if(!first&&!out(o,",",1))return false;if(!canonical(p,c,o))return false;first=false;}return out(o,"]",1);}if(t->kind=='{'){const char*order[]={"name","idName","embedded","version","properties","indexes","type","target","unique","hash",NULL};if(!out(o,"{",1))return false;bool first=true;for(unsigned i=0;order[i];i++){unsigned n=get(p,id,order[i]);if(!n)continue;if(!first&&!out(o,",",1))return false;if(!quoted(o,order[i])||!out(o,":",1)||!canonical(p,n,o))return false;first=false;}return out(o,"}",1);}return false;}
unsigned char *TIOCaptureCanonicalSchema(const unsigned char*b,size_t n,size_t*length){if(length)*length=0;if(!b||!n||n>65536||!length)return NULL;Parser*p=calloc(1,sizeof(*p));if(!p)return NULL;p->b=b;p->n=n;unsigned root=value(p,1);ws(p);Output o={0};if(root&&p->p==n&&validate(p,root)){o.b=malloc(65536);if(o.b&&!canonical(p,root,&o)){memset(o.b,0,o.n);free(o.b);o.b=NULL;}}memset(p,0,sizeof(*p));free(p);if(o.b)*length=o.n;return o.b;}
